<script>
function selectBill(el) {
    document.querySelectorAll('.bill_tab').forEach(tab => tab.classList.remove('selected'));
    el.classList.add('selected');
    document.getElementById('monthly_bill').value = el.getAttribute('data-value');
}

document.getElementById("klandingForm").addEventListener("submit", function (e) {
    e.preventDefault();

    let form = this;
    let formData = new FormData(form);
    let hasError = false;

    // Clear previous errors
    document.querySelectorAll(".error-message").forEach(el => el.textContent = "");

    // Fields
    const fullName = document.getElementById("full_name");
    const phone = document.getElementById("phone");
    const email = document.getElementById("email");
    const pincode = document.getElementById("pincode");
    const monthlyBill = document.getElementById("monthly_bill");
    const submitBtn = form.querySelector("button[type='submit']");

    // Disable button
    submitBtn.disabled = true;
    submitBtn.textContent = "Submitting...";

    // Validations
    if (!fullName.value.trim()) {
        showError(fullName, "Full Name is required.");
        hasError = true;
    }

    if (!phone.value.trim()) {
        showError(phone, "Contact Number is required.");
        hasError = true;
    } else if (!/^[0-9]{10,15}$/.test(phone.value.trim())) {
        showError(phone, "Phone number must be between 10 and 15 digits.");
        hasError = true;
    }

    if (!email.value.trim()) {
        showError(email, "Email is required.");
        hasError = true;
    } else if (!/^\S+@\S+\.\S+$/.test(email.value.trim())) {
        showError(email, "Enter a valid email address.");
        hasError = true;
    }

    if (!pincode.value.trim()) {
        showError(pincode, "Pincode is required.");
        hasError = true;
    } else if (!/^[0-9]{6}$/.test(pincode.value.trim())) {
        showError(pincode, "Enter a valid 6-digit pincode.");
        hasError = true;
    }

    if (!monthlyBill.value.trim()) {
        showError(monthlyBill, "Please select your monthly bill.");
        hasError = true;
    }

    if (hasError) {
        submitBtn.disabled = false;
        submitBtn.textContent = "Get a Free Quote";
        return;
    }

    fetch(form.action, {
        method: "POST",
        headers: {
            "X-CSRF-TOKEN": document.querySelector('input[name="_token"]').value
        },
        body: formData
    })
    .then(res => res.json())
    .then(data => {
        if (data.status && data.redirect) {
            window.location.href = data.redirect;
        } else {
            alert("Something went wrong. Please try again.");
            submitBtn.disabled = false;
            submitBtn.textContent = "Get a Free Quote";
        }
    })
    .catch(error => {
        console.error("Form submission error:", error);
        alert("There was a problem submitting the form.");
        submitBtn.disabled = false;
        submitBtn.textContent = "Get a Free Quote";
    });

    function showError(inputElement, message) {
        const errorEl = inputElement.nextElementSibling;
        if (errorEl && errorEl.classList.contains("error-message")) {
            errorEl.textContent = message;
        }
    }
});
</script>


